import heapq
def top_k_frequent(lists, k):
    freq = {}
    for list in lists:
        for i in list:
            if i not in freq:
                freq[i] = 0
            freq[i] += 1
    heap = []
    for i in freq:
        if len(heap) < k:
            heapq.heappush(heap, (freq[i], i))
        elif freq[i] > heap[0][0]:
            heapq.heappop(heap)
            heapq.heappush(heap, (freq[i], i))
    return [i for _, i in heap]

